--
-- Name: slugify(text); Type: FUNCTION; Schema: quranhub_schema; Owner: quranhub_prod
--

CREATE FUNCTION quranhub_schema.slugify(text text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
BEGIN
    -- Remove accents (basic transliteration)
    -- Lowercase
    text := lower(text);

    -- Remove all non-word characters except spaces and hyphens
    text := regexp_replace(text, '[^\w\s-]', '', 'g');

    -- Replace spaces and underscores with hyphens
    text := regexp_replace(text, '[-\s]+', '-', 'g');

    -- Trim hyphens
    text := regexp_replace(text, '(^-+)|(-+$)', '', 'g');

    RETURN text;
END;
$_$;


ALTER FUNCTION quranhub_schema.slugify(text text) OWNER TO quranhub_prod;

--
-- Name: test_search(text, boolean); Type: FUNCTION; Schema: quranhub_schema; Owner: quranhub_prod
--

CREATE FUNCTION quranhub_schema.test_search(p_keyword text, p_exact boolean DEFAULT true) RETURNS TABLE(verse_number integer, text_preview text, score double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_exact THEN
        RETURN QUERY
        SELECT 
            number,
            substring(text, 1, 100),
            1.0::float as score
        FROM quranhub_schema.ayat
        WHERE edition_id = 78
        AND lower(text) LIKE lower('%' || p_keyword || '%')
        LIMIT 10;
    ELSE
        RETURN QUERY
        SELECT 
            number,
            substring(text, 1, 100),
            similarity(text, p_keyword)
        FROM quranhub_schema.ayat
        WHERE edition_id = 78
        AND text % p_keyword
        ORDER BY similarity(text, p_keyword) DESC
        LIMIT 10;
    END IF;
END;
$$;


ALTER FUNCTION quranhub_schema.test_search(p_keyword text, p_exact boolean) OWNER TO quranhub_prod;

