INSERT INTO quranhub_schema.ayat VALUES (681676, 16, 136, 14, 1952, '安拉说：“[人类啊！]你们不要崇拜两个主宰，应受崇拜的主宰只有一个[注][即安拉]，你们只能畏惧我。”', 51, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (691816, 16, 139, 14, 1952, '[{"word_arabic":"وَقَالَ","word_ayah":51,"word_number_in_ayah":1,"word_number_in_quran":34795,"word_number_in_surah":652,"word_translation":"And Allah has said","word_transliteration":"waqala"},{"word_arabic":"اللَّهُ","word_ayah":51,"word_number_in_ayah":2,"word_number_in_quran":34796,"word_number_in_surah":653,"word_translation":"And Allah has said","word_transliteration":"al-lahu"},{"word_arabic":"لَا","word_ayah":51,"word_number_in_ayah":3,"word_number_in_quran":34797,"word_number_in_surah":654,"word_translation":"(Do) not","word_transliteration":"la"},{"word_arabic":"تَتَّخِذُوا","word_ayah":51,"word_number_in_ayah":4,"word_number_in_quran":34798,"word_number_in_surah":655,"word_translation":"take","word_transliteration":"tattakhidhu"},{"word_arabic":"إِلَهَيْنِ","word_ayah":51,"word_number_in_ayah":5,"word_number_in_quran":34799,"word_number_in_surah":656,"word_translation":"[two] gods","word_transliteration":"ilahayni"},{"word_arabic":"اثْنَيْنِ","word_ayah":51,"word_number_in_ayah":6,"word_number_in_quran":34800,"word_number_in_surah":657,"word_translation":"two","word_transliteration":"ith''nayni"},{"word_arabic":"إِنَّمَا","word_ayah":51,"word_number_in_ayah":7,"word_number_in_quran":34801,"word_number_in_surah":658,"word_translation":"only","word_transliteration":"innama"},{"word_arabic":"هُوَ","word_ayah":51,"word_number_in_ayah":8,"word_number_in_quran":34802,"word_number_in_surah":659,"word_translation":"He","word_transliteration":"huwa"},{"word_arabic":"إِلَهٌ","word_ayah":51,"word_number_in_ayah":9,"word_number_in_quran":34803,"word_number_in_surah":660,"word_translation":"(is) God","word_transliteration":"ilahun"},{"word_arabic":"وَاحِدٌ","word_ayah":51,"word_number_in_ayah":10,"word_number_in_quran":34804,"word_number_in_surah":661,"word_translation":"One","word_transliteration":"wahidun"},{"word_arabic":"فَإِيَّايَ","word_ayah":51,"word_number_in_ayah":11,"word_number_in_quran":34805,"word_number_in_surah":662,"word_translation":"so Me Alone","word_transliteration":"fa-iyyaya"},{"word_arabic":"فَارْهَبُونِ","word_ayah":51,"word_number_in_ayah":12,"word_number_in_quran":34806,"word_number_in_surah":663,"word_translation":"you fear [Me]","word_transliteration":"fa-ir''habuni"}]', 51, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (710524, 16, 142, 14, 1952, '۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوۤا۟ إِلَـٰهَیۡنِ ٱثۡنَیۡنِۖ إِنَّمَا هُوَ إِلَـٰهࣱ وَ ٰحِدࣱ فَإِیَّـٰیَ فَٱرۡهَبُونِ ', 51, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (735265, 16, 147, 14, 1952, 'قال الإِمام الرازى : اعلم أنه - سبحانه - لما بين فى الآيات الأولى ، أن ما سوى الله - تعالى - سواء أكان من عالم الأرواح أم من عالم الأجسام ، منقاد وخاضع لجلاله - تعالى - وكبريائه - أتبعه فى هذه الآية بالنهى عن الشرك ، وببيان أن كل ما سواه واقع فى ملكه وتحت تصرفه ، وأنه غنى عن الكل ، فقال - تعالى - : ( وَقَالَ الله لاَ تَتَّخِذُواْ إلهين اثنين . . . ) .أى : وقال الله - تعالى - لعباده عن طريق رسله عليهم الصلاة والسلام - لا تتخذوا شركاء معى فى العبادة والطاعة ، بل اجعلوهما لى وحدى ، فأنا الخالق لكل شئ والقادر على كل شئ .قال الآلوسى : وقوله ( وقال الله . . ) معطوف على قوله - سبحانه - ( وَلِلَّهِ يَسْجُدُ مَا فِي السماوات وَمَا فِي الأرض . . ) وإظهار الفاعل ، وتخصيص لفظ الجلالة بالذكر ، للإِيذان بأنه - تعالى - متعين الألوهية والمنهى عنه هو الاشراك به ، لا أن المنهى عنه هو مطلق اتخاذ إلهين . . .( اثنين ) صفة للفظ إلهين أو مؤكد له . وخص هذا العدد بالذكر ، لأنه الأقل ، فيعلم انتفاء اتخاذ ما فوقه بالطريق الأولى .وقوله - سبحانه - ( إِنَّمَا هُوَ إله وَاحِدٌ ) بيان وتوكيد لما قبله ، وهو مقول لقوله - سبحانه - ( وقال الله ) .أى : وقال الله لا تتخذوا معى فى العبادة إلها آخر ، وقال - أيضا - إنما المستحق للعبادة إله واحد ، والقصر فى الجملة الكريمة من قصر الموصوف على الصفة ، أى : الله وحده هو المختص بصفة الوحدانية .وقد نهى - سبحانه - عن الشرك فى آيات كثيرة ، وأقام الأدلة على بطلانه ومن ذلك قوله - تعالى - ( . . . وَلاَ تَجْعَلْ مَعَ الله إلها آخَرَ فتلقى فِي جَهَنَّمَ مَلُوماً مَّدْحُوراً ) وقوله - سبحانه - ( لَوْ كَانَ فِيهِمَآ آلِهَةٌ إِلاَّ الله لَفَسَدَتَا فَسُبْحَانَ الله رَبِّ العرش عَمَّا يَصِفُونَ ) والفاء فى قوله ( فإياى فارهبون ) واقعة فى جواب شرط مقدر و ( إياى ) مفعول به لفعل محذوف يقدر مؤخرا ، يدل عليه قوله ( فارهبون ) .والرهبة : الخوف المصحوب بالتحرز ، وفعله رهب بزنة طرب .والمعنى : إن رهبتم شيئا فإياى فارهبوا دون غيرى ، لأنى أنا الذى لا يعجزنى شئ .وفى الجملة الكريمة التفات من الغيبة إلى الخطاب ، للمبالغة فى التخويف ، إذ تخويف الحاضر أبلغ من تخويف الغائب ، لاسيما بعد أن وصف - سبحانه - ذاته بما وصف من صفات القهر والغلبة والكبرياء .وقدم المفعول وهو إياى لإِفادة الحصر ، وحذف متعلق الرهبة ، للعموم .أى : ارهبونى فى جميع ما تأتون وما تذرون .والمتأمل فى هذه الآية الكريمة يراها قد اشتملت على ألوان من المؤكدات للنهى عن الشرك ، والأمر بإخلاص العبادة لله - تعالى - وحده ، تارة عن طريق التقرير ( وقال الله .. ) وتارة عن طريق النهى الصريح ، وتارة عن طريق القصر وتارة عن طريق التخصيص .وذلك لكى يقلع الناس عن هذه الرذيلة النكراء ، ويؤمنوا بالله الواحد القهار .', 51, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (741501, 16, 149, 14, 1952, '{ وَقَالَ ٱللَّهُ لاَ تَتَّخِذُواْ إِلـٰهَيْنِ ٱثْنَيْنِ إِنَّمَا هُوَ إِلـٰهٌ وَاحِدٌ فَإيَّايَ فَٱرْهَبُونِ }
INSERT INTO quranhub_schema.ayat VALUES (698, 5, 1, 6, 698, 'إني أريد أن ترجع حاملا إثم قَتْلي، وإثمك الذي عليك قبل ذلك، فتكون من أهل النار وملازميها، وذلك جزاء المعتدين.', 29, 2, 112, 90, NULL, 45, 12);
INSERT INTO quranhub_schema.ayat VALUES (753973, 16, 146, 14, 1952, 'لما أُشبع القول في إبطال تعدّد الآلهة الشائع في جميع قبائل العرب ، وأتبع بإبطال الاختلاق على الرسول صلى الله عليه وسلم والقرآن ، نُقل الكلام إلى إبطال نوع آخر من الشّرك متّبع عند قبائل من العرب وهو الإشراك بإلهية أصلين للخير والشرّ ، تقلّدته قبائل العرب المجاورة بلاد فارس والساري فيهم سلطان كِسرى وعوائدُهم ، مثلُ بني بكر بن وائل وبني تميم ، فقد دان منهم كثير بالمجوسية ، أي المَزْدكية والمانوية في زمن كِسرى أبرويش وفي زمن كِسرى أنوشروان ، والمجوسية تثبت عقيدةً بإلهين : إلهٍ للخير وهو النّور ، وإلهٍ للشرّ وهو الظلمة ، فإله الخير لا يصدر منه إلا الخير والأنعام ، وإله الشرّ لا يصدر عنه إلا الشرّ والآلام ، وسمّوا إله الخير ( يَزْدَان ) ، وسموا إله الشرّ ( اَهْرُمُنْ ). وزعموا أن يزدان كان منفرداً بالإلهية وكان لا يخلق إلا الخير فلم يكن في العالم إلا الخير ، فخطر في نفسه مرةً خاطرُ شرّ فتولّد عنه إلهٌ آخرُ شريك له هو إلهٌ الشرّ ، وقد حكى هذا المعرّي في لزومياته بقوله :فَكّرَ يَزْدانُ على غِرة ... فصيغ من تفكيره أهْرُمُنْولم يكونوا يجعلون لهذين الأصلين صُوراً مجسّمة ، فلذلك لم يكن دينهم من عداد عبادة الطاغوت لاختصاص اسم الطاغوت بالصور والأجسام المعبودة . وهذا الدين من هذه الجهة يشبه الأديان التي لا تعبُد صُوَراً محسوسة . وسيأتي الكلام على المجوسيّة عند تفسير قوله تعالى : { إن الذين آمنوا والذين هادوا إلى قوله { والمَجوسَ } في سورة الحج ( 170 ).ويدلّ على أن هذا الدين هو المراد التّعقيب بآية { ما بكم من نعمة فمن الله ثم إذا مسّكم الضرّ فإليه تجأرون } [ سورة النحل : 53 ] كما سيأتي .فقوله تعالى : { وقال الله لا تتخذوا إلهين اثنين } عطف قصّة على قصّة وهو مرتبط بجملة { ولقد بعثنا في كل أمّة رسولاً أن اعبدوا الله واجتنبوا الطاغوت } [ سورة النحل : 36 ].ومعنى { وقال الله لا تتخذوا إلهين } أنه دعا الناس ونَصب الأدلّة على بطلان اعتقاده . وهذا كقوله تعالى : { يريدون أن يبدلوا كلام الله } [ سورة الفتح : 15 ] وقوله : { كذلكم قال الله من قبل } [ سورة الفتح : 15 ].وصيغة التّثنية من قوله : { إلهين } أكدت بلفظ { اثنين } للدّلالة على أن الإثنينية مقصودة بالنّهي إبطالاً لشرك مخصوص من إشراك المشركين ، وأن لا اكتفاء بالنّهي عن تعدّد الإله بل المقصود النّهي عن التّعدد الخاص وهو قول المجوس بإلهين . ووقع في «الكشاف» توجيه ذكر { اثنين } بأنه لدفع احتمال إرادة الجنس حقيقة لا مجازاً .وإذ نُهوا عن اتخاذ إلهين فقد دلّ بدلالة الاقتضاء على إبطال اتخاذ آلهة كثيرة .وجملة { إنما هو إله واحد } يجوز أن تكون بياناً لجملة { لا تتخذوا إلهين اثنين } ، فالجملة مقولة لفعل { وقال الله } لأن عطف البيان تابع للمبيّن كموقع الجملة الثانية في قول الشاعر :أقول له ارحَلْ لا تَقيمَنّ عندنا ... فلذلك فُصلت ، وبذلك أفيد بالمنطوق ما أفيد قبلُ بدلالة الاقتضاء .والضمير من قوله تعالى : { إنما هو إله واحد } عائد إلى اسم الجلالة في قوله : { وقال الله } ، أي قال الله إنما الله إله واحد ، وهذا جَريٌ على أحد وجهين في حكاية القول وما في معناه بالمعنى كما هنا ، وقوله تعالى حكاية عن عيسى عليه السلام { أن اعبدوا الله ربي وربكم } [ سورة المائدة : 117 ] ف { أن اعبدوا الله } مفسرُ «أمَرْتني» ، وفعل «أمَرْتني» فيه معنى القول ، والله قال له : قل لهم اعبُدوا الله ربك وربهم ، فحكاه بالمعنى ، فقال : ربّي .والقصر في قوله : { إنما هو إله واحد } قصر موصوف على صفة ، أي الله مختصّ بصفة توحّد الإلهية ، وهو قصر قلب لإبطال دعوى تثنية الإله .ويجوز أن تكون جملة { إنما هو إله واحد } معترضةً واقعة تعليلاً لجملة { لا تتخذوا إلهين اثنين } أي نَهى الله عن اتخاذ إلهين لأن الله واحد ، أي والله هو مسمّى إله فاتّخاذ إلهين اثنين قلب لحقيقة الإلهية .وحصر صفة الوحدانية في عَلَم الجلالة بالنّظر إلى أن مسمّى ذلك العلم مساوٍ لمسمّى إله ، إذ الإله منحصر في مسمّى ذلك العلَم .وتفريع { فإياي فارهبون } يجوز أن يكون تفريعاً على جملة { لا تتخذوا إلهين اثنين } فيكون { فإياي فارهبون } من مقول القول ، ويكون في ضمير المتكلم من قوله : { فارهبون } التفات من الغيبة إلى الخطاب .ويجوز أن يكون تفريعاً على فعل { وقال الله } فلا يكون من مقول القول ، أي قال الله لا تتخذوا إلهين فلا ترهبوا غيري . وليس في الكلام التفات على هذا الوجه .وتفرّع على ذلك قوله تعالى : { فإياي فارهبون } بصيغة القصر ، أي قصر قلب إضافياً ، أي قصر الرهبة التامة منه عليه فلا اعتداد بقدرة غيره على ضرّ أحد . وهو ردّ على الذين يرهبون إله الشرّ فالمقصود هو المرهوب .والاقتصار على الأمر بالرّهبة وقصرها على كونها من الله يفهم منه الأمر بقصر الرغبة عليه لدلالة قصر الرهبة على اعتقاد قصر القدرة التامة عليه تعالى فيفيد الردّ على الذين يطمعون في إله الخير بطريق الأولى ، وإنما اقتصر على الرّهبة لأن شأن المزدكية أن تكون عبادتهم عن خوف إله الشرّ لأن إله الخير هم في أمن منه فإنه مطبوع على الخير .ووقع في ضمير { فإياي } التفات من الغيبة إلى التكلم لمناسبة انتقال الكلام من تقرير دليل وحدانية الله على وجه كلّي إلى تعيين هذا الواحد أنه الله منزل القرآن تحقيقاً لتقرير العقيدة الأصلية . وفي هذا الالتفات اهتمام بالرّهبة لما في الالتفات من هزّ فهم المخاطبين . وتقدّم تركيب نظيره بدون التفات في سورة البقرة .واقتران فعل { فارهبون } بالفاء ليكون تفريعاً على تفريع فيفيد مفاد التأكيد لأن تعلّق فعل «ارهبون» بالمفعول لفظاً يجعل الضمير المنفصل المذكور قبله في تقدير معمول لفعل آخر ، فيكون التقدير : فإياي ارهبُوا فارهبون ، أي أمرتكم بأن تقصُروا رهبتكم عليّ فارهبون امتثالاً للأمر .', 51, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (1953, 16, 1, 14, 1953, 'ولله كل ما في السموات والأرض خلقًا وملكًا وعبيدًا، وله وحده العبادة والطاعة والإخلاص دائمًا، أيليق بكم أن تخافوا غير الله وتعبدوه؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (8189, 16, 2, 14, 1953, 'Göylərdə və yerdə nə varsa, hamısı Onundur! Din də (itaət və ibadət də) daim Onundur. Belə olduğu təqdirdə Allahdan başqasındanmı qorxursunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (14425, 16, 3, 14, 1953, 'Göylərdə və yerdə nə varsa, Onundur. Din də daim Ona məxsusdur. Siz Allahı qoyub başqasındanmı qorxursunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (245159, 16, 40, 14, 1955, 'apoi când îndepărtează nenorocirea de la voi, unii dintre voi îi alătură pe alţii Domnului lor,', 54, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (26897, 16, 5, 14, 1953, 'Jemu náleží vše, co na nebesích i na zemi je, a Jemu patří i uctívání nezbytné. Zdaž jiného než Boha bát se budete?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (33133, 16, 6, 14, 1953, 'Jemuť přináleží, cožkoliv na nebi jest i na zemi, jemu přináleží uctívání věčné: zdaž jiného báti se budete, kromě Boha?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (39369, 16, 7, 14, 1953, 'Und Sein ist, was in den Himmeln und auf Erden ist, und Ihm gebührt die immerwährende Furcht. Wollt ihr also einen anderen fürchten außer Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (45605, 16, 8, 14, 1953, 'Ihm gehört (alles), was in den Himmeln und auf der Erde ist, und Sein ist immerwährend die Religion. Wollt ihr denn einen anderen als Allah fürchten?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (51841, 16, 9, 14, 1953, 'Ihm gehört, was in den Himmeln und auf der Erde ist. Und Ihm gehört die religiöse Verehrung in ständiger Weise. Wollt ihr denn einen anderen als Gott fürchten?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (58077, 16, 10, 14, 1953, 'Und Ihm gehört, was in den Himmeln und auf Erden ist. Und Ihm gehört der Din für immer. Handelt ihr etwa Taqwa gemäß (anderen) außer ALLAH gegenüber?!', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (64313, 16, 11, 14, 1953, 'އަދި އުޑުތަކާއި، ބިމުގައިވާހާ އެއްޗެއް މިލްކުވެގެންވަނީ، އެކަލާނގެއަށެވެ. އަދި އަބަދުގެ އަބަދަށް، ކިޔަމަންވުންވަނީވެސް އެކަލާނގެއަށެވެ. ފަހެ، ތިޔަބައިމީހުން ބިރުވެތިވަނީ، اللَّه ނޫން ފަރާތަކަށް ހެއްޔެވެ؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (70549, 16, 12, 14, 1953, 'Whatsoever is in the heavens and the earth belongs to Him, and His the judgement for ever. So will you fear any other than God?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (76785, 16, 13, 14, 1953, 'And to Him only belongs all whatever is in the heavens and in the earth, and obeying Him only is obligatory; so will you fear anyone other than Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (83021, 16, 14, 14, 1953, 'To Him belongs all that is in the heavens and earth; His is the religion for ever. Then will you fear other than God?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (89257, 16, 15, 14, 1953, 'And His is all that is in the heavens and on earth, and to Him [alone] obedience is always due: will you, then, pay reverence to aught but Him?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (95493, 16, 16, 14, 1953, 'And His is whatsoever is in the heavens and the earth, and unto Him is obedience due perpetually; will ye then fear any other than Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (101729, 16, 17, 14, 1953, 'To Him belongs all that is in the heavens and (all that is in) the earth and Ad-Din Wasiba is His [(i.e. perpetual sincere obedience to Allah is obligatory). None has the right to be worshipped but Allah)]. Will you then fear any other than Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (107965, 16, 18, 14, 1953, 'Unto Him belongeth whatsoever is in the heavens and the earth, and religion is His for ever. Will ye then fear any other than Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (114201, 16, 19, 14, 1953, 'To Him belongs all that is in the heavens and the earth. His is the Religion for ever. Would you then fear any but Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (120437, 16, 20, 14, 1953, 'And to Him belongs whatever is in the heavens and the earth, and to Him is [due] worship constantly. Then is it other than Allah that you fear?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (1182181, 56, 297, 27, 5056, NULL, 77, 7, 537, 471, NULL, 215, 54);
INSERT INTO quranhub_schema.ayat VALUES (126673, 16, 21, 14, 1953, 'To Him belongs all that is in the heavens and the earth. God''s retribution is severe. Should you then have fear of anyone other than God?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (132909, 16, 22, 14, 1953, 'To Him belongs whatever is in the heavens and on earth, and to Him is duty due always: then will ye fear other than Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (139145, 16, 23, 14, 1953, 'هر چه در آسمانها و زمين است از آن اوست و پرستش خاص اوست. آيا از غير خدا مى‌ترسيد؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (145381, 16, 24, 14, 1953, 'و آنچه در آسمانها و زمين است از آنِ اوست، و آيين پايدار [نيز] از آنِ اوست. پس آيا از غير خدا پروا داريد؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (151617, 16, 25, 14, 1953, 'و هر چه در آسمانها و زمین است همه ملک خداست و دین و اطاعت همیشه مخصوص اوست، آیا شما بندگان از کسی غیر از خدای مقتدر می‌ترسید؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (157853, 16, 26, 14, 1953, 'آنچه در آسمانها و زمین است، از آن اوست؛ و دین خالص (نیز) همواره از آن او می‌باشد؛ آیا از غیر او می‌ترسید؟!', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (164089, 16, 27, 14, 1953, 'C''est à Lui qu''appartient ce qui est dans les cieux et sur la terre; c''est à Lui que l''obéissance perpétuelle est due. Craindriez-vous donc, d''autres qu''Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (170325, 16, 28, 14, 1953, 'Kuma Yana da abin da yake a cikin sammai da ƙasa, kuma Yana da addini wanda yake dawwamamme. Shin fa, wanin Allah kuke bĩ da taƙãwa?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (176561, 16, 29, 14, 1953, 'और जो कुछ आसमानों में हैं और जो कुछ ज़मीन में हैं (ग़रज़) सब कुछ उसी का है और ख़ालिस फरमाबरदारी हमेशा उसी को लाज़िम (जरूरी) है तो क्या तुम लोग ख़ुदा के सिवा (किसी और से भी) डरते हो', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (182797, 16, 30, 14, 1953, 'Dan kepunyaan-Nya-lah segala apa yang ada di langit dan di bumi, dan untuk-Nya-lah ketaatan itu selama-lamanya. Maka mengapa kamu bertakwa kepada selain Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (189033, 16, 31, 14, 1953, 'A Lui appartiene tutto ciò che c''è nei cieli e sulla terra, a Lui spetta il culto sempiterno. Temerete altri che Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (195269, 16, 32, 14, 1953, '天と地とにある凡てのものは，かれに属し，また服従は絶えずかれに対してだけある。それであなたがたは，アッラー以外に（何を）畏れるのか。', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (201505, 16, 33, 14, 1953, '천지의 모든 것이 그 분에게귀속되어 있어 이 모든 것이 항상그분께 순종하거늘 너희는 하나 님외에 다른 것을 두려워 한단 말이뇨', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (376113, 16, 61, 14, 1953, 'Göklerde ve yerde olan her şey yalnız O''nundur. Din de daima O''nundur. Böyle iken, siz Allah''tan başkasından mı korkarsınız?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (760209, 16, 144, 14, 1952, NULL, 51, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (207741, 16, 34, 14, 1953, 'هه‌رچی له ئاسمانه‌کان و زه‌ویدا هه‌یه هه‌ر ئه‌و زاته خاوه‌نیانه‌، هه‌میشه‌و به‌رده‌وام هه‌ر ئه‌و زاته‌یه که شایسته‌ی ئه‌وه بێت ئاین و به‌رنامه‌و فه‌رمانڕه‌وایی له‌و وه‌ربگیرێت و ملکه‌چی هه‌ر بۆ ئه‌و بکرێت، ئایا ڕه‌وایه بێجگه له خوا له که‌سی تر بپه‌رستن و حسابی بۆ بکه‌ن؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (213977, 16, 35, 14, 1953, 'അവന്‍റെതാകുന്നു ആകാശങ്ങളിലുള്ളതും ഭൂമിയിലുള്ളതും. നിരന്തരമായിട്ടുള്ള കീഴ്‌വണക്കം അവന്ന് മാത്രമാകുന്നു. എന്നിരിക്കെ അല്ലാഹു അല്ലാത്തവരോടാണോ നിങ്ങള്‍ ഭക്തികാണിക്കുന്നത്‌?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (220213, 16, 36, 14, 1953, 'Hem behoort alles wat in den hemel en op de aarde is, en hem is de mensch eeuwig gehoorzaamheid schuldig. Zoudt gij dus iets buiten God vreezen?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (226449, 16, 37, 14, 1953, 'Ham tilhører alt i himlene og på jorden. Hans er religionen for alltid. Skulle dere vel frykte noen annen enn Gud?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (232685, 16, 38, 14, 1953, 'Do Niego należy to, co jest w niebiosach, i to, co jest na ziemi. Jego religia jest na zawsze. Czy będziecie okazywać bogobojność względem kogoś innego aniżeli Boga?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (238921, 16, 39, 14, 1953, 'Seu é tudo quanto existe nos céus e na terra. Somente a Ele devemos obediência permanente. Temeríeis, acaso, alguémalém de Deus?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (245157, 16, 40, 14, 1953, 'Ale Lui sunt cele din ceruri şi de pe pământ. A Lui este legea cea veşnică. Vă temeţi de altcineva în afară de Dumnezeu?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (251393, 16, 41, 14, 1953, 'Ему принадлежит то, что на небесах и на земле. Ему одному надлежит поклоняться. Неужели вы станете бояться кого-либо помимо Аллаха?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (257629, 16, 42, 14, 1953, 'Ему принадлежит то, что на небесах и на земле, Ему должно всегда поклоняться. Неужели вы страшитесь кого-либо другого, кроме Аллаха?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (263865, 16, 43, 14, 1953, 'Ведь, истинно, Ему принадлежит Все в небесах и на земле, И неустанное служение - Ему! Так неужели вы иных (богов), кроме Аллаха, (Способны чтить) и станете страшиться?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (270101, 16, 44, 14, 1953, '۽ جيڪي آسمانن ۽ زمين ۾ آھي سو سندس آھي ۽ اُن جي عبادت سدائين (لازم) آھي، پوءِ الله کانسواءِ ٻـين کان ڇو ڊڄندا آھيو؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (276337, 16, 45, 14, 1953, 'Eebe waxaa u sugnaaday waxa Samooyinka iyo Dhulka ku sugan, waxaana u sugnaaday Diin (Cibaado) Joogta ah, ee nia Eebe cidaan ahayn yaad ka dhawrsanaysaan.', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (282573, 16, 46, 14, 1953, 'Vetëm e Tij është çka ka në qiej e në tokë, dhe vetëm Atij i takon vazhdimisht adhurimi. A mos i keni frikë dikujt tjetër pos All-llahut?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (288809, 16, 47, 14, 1953, 'E tij është gjithçka është në qiej dhe në tokë dhe feja e tij është e qëndrueshme. A t’i frikësoheni tjetërkujt përveç All-llahut?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (295045, 16, 48, 14, 1953, 'Dhe, Atij i përket çdo gjë që gjendet në qiej dhe në Tokë dhe Atij i përket bindja përherë. A, mos vallë, përpos Perëndisë, kujt t’i druani tjetër?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (301281, 16, 49, 14, 1953, 'Honom tillhör allt i himlarna och på jorden och ni är skyldiga Honom ständig lydnad. Fruktar ni någon annan än Gud', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (307517, 16, 50, 14, 1953, 'Na ni vyake Yeye viliomo katika mbingu na ardhi. Na Dini ni yake Yeye daima. Je! Mtamcha mwengine asiye kuwa Mwenyezi Mungu?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (313753, 16, 51, 14, 1953, 'வானங்களிலும், பூமியிலும் உள்ளவை(யெல்லாம்) அவனுக்கே (சொந்தமானவை) அவனுக்கே (என்றென்றும்) வழிபாடு உரியதாக இருக்கிறது (உண்மை இவ்வாறிருக்க) அல்லாஹ் அல்லாதவற்றையா நீங்கள் அஞ்சகிறீர்கள்?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (319989, 16, 52, 14, 1953, 'Ҳарчи дар осмонҳову замин аст, аз они Ӯст ва парастиш хоси Ӯст. Оё аз ғайри Худо метарсед?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (326225, 16, 53, 14, 1953, 'และเป็นกรรมสิทธิ์ของพระองค์ สิ่งที่อยู่ในชั้นฟ้าทั้งหลายและแผ่นดิน และการภักดีต่อพระองค์เท่านั้นจำเป็นต้องมีประจำ ดังนั้นพวกเจ้าจะยำเกรงผู้ใดอื่นจากอัลลอฮ์กระนั้นหรือ?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (332461, 16, 54, 14, 1953, 'Göklerde ve yerde ne varsa hepsi O''nundur. Kulluğun da yalnız O''na yapılması lazımdır. Siz, Allah''tan başkasından mı korkuyorsunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (338697, 16, 55, 14, 1953, 'Göklerde ve yerde ne varsa O''nundur, itaat-kulluk da (din de) sürekli olarak O''nundur. Böyleyken Allah''tan başkasından mı korkup-sakınıyorsunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (344933, 16, 56, 14, 1953, 'Göklerde ve yerde olan O''nundur. Kulluk da daima O''nadır. Allah''tan başkasından mı sakınıyorsunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (351169, 16, 57, 14, 1953, 'Onundur ne varsa göklerde ve ne varsa yeryüzünde, ibadet ve itaat de daima onadır, hala mı Allah''tan başka birinden çekinmede, korkmadasınız?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (357405, 16, 58, 14, 1953, 'Göklerde ve yerde ne varsa O''nundur. Din de sürekli olarak yalnız O''nundur. Hâlâ, Allah''tan başkasından mı sakınıyorsunuz!', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (363641, 16, 59, 14, 1953, 'velehû mâ fi-ssemâvâti vel''arḍi velehü-ddînü vâṣibâ. efegayra-llâhi tetteḳûn.', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (369877, 16, 60, 14, 1953, 'Göklerde ve yerde ne varsa, O''nundur, din de yalnız O''nundur. O halde Allah''tan başkasından mı korkuyorsunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (382349, 16, 62, 14, 1953, 'Göklerde ne var, yerde ne varsa hep O''nundur.İtaat daima O’nadır.Öyle iken Allah’tan başkasından mı korkuyorsunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (388585, 16, 63, 14, 1953, 'Göklerde ve yerde ne varsa O''nundur. Din de sürekli sadece O''nundur. ALLAH''tan başkasını mı sayıyorsunuz?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (394821, 16, 64, 14, 1953, 'Җирдә вә күкләрдә булган нәрсәләр Аллаһ мөлкедер вә хак дин – Аллаһ динедер, ягъни ислам дине генә диндер, башка диннәр вә Коръән сөннәттән башка гамәлләр – барысы да батылдыр. Әйә сез Аллаһудан башкадан куркасызмы?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (401057, 16, 65, 14, 1953, 'ئاسمانلاردىكى ۋە زېمىندىكى ھەممە نەرسە اﷲ نىڭ مۈلكىدۇر، ئىبادەت ھەمىشە اﷲ قا خاستۇر، اﷲ تىن بۆلەك غەيرىدىن قورقامسىلەر؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (407293, 16, 66, 14, 1953, 'اوراسی کا ہے جوکچھ آسمانوں اور زمین میں ہے اور عبادت اسی کی لازم ہے پھرکیا الله کے سوا اوروں سے ڈرتے ہو', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (413529, 16, 67, 14, 1953, 'اور جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب اسی کا ہے اور اسی کی عبادت لازم ہے۔ تو تم خدا کے سوا اوروں سے کیوں ڈرتے ہو', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (419765, 16, 68, 14, 1953, 'اور اسی کے لئے زمین و آسمان کی ہر شے ہے اور اسی کے لئے دائمی اطاعت بھی ہے تو کیا تم غیر خدا سے بھی ڈرتے ہو', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (426001, 16, 69, 14, 1953, 'اور اسی کا ہے جو کچھ آسمانوں اور زمین میں ہے اور اسی کی فرمانبرداری لازم ہے، تو اللہ کے سوا کسی دوسرے سے ڈرو گے،', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (432237, 16, 70, 14, 1953, 'اور جو کچھ آسمانوں اور زمین میں ہے (سب) اسی کا ہے اور (سب کے لئے) اسی کی فرمانبرداری واجب ہے۔ تو کیا تم غیر اَز خدا (کسی) سے ڈرتے ہو،', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (438473, 16, 71, 14, 1953, 'Осмонлару ердаги нарсалар Уникидир. Дин ҳам бардавом Уникидир. Аллоҳдан ўзгадан қўрқасизларми?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (444709, 16, 72, 14, 1953, 'His is whatever is in the heavens and the earth, and obedience to Him inevitably pervades the whole universe. Will you, then, hold in awe any other than Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (450945, 16, 73, 14, 1953, 'And whatever is in the heavens and the earth is His, and to Him should obedience be (rendered) constantly; will you then guard against other than (the punishment of) Allah?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (457181, 16, 74, 14, 1953, 'Wa lahoo maa fis samaawaati wal ardi wa lahud deenu waasibaa; afaghairal laahi tattaqoon', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (463417, 16, 75, 14, 1953, 'Suyo es lo que está en los cielos y en la tierra. Se le debe un culto permanente. ¿Vais a temer a otro diferente de Alá?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (469653, 16, 76, 14, 1953, 'آنچه در آسمان ها و زمین است، فقط در سیطره مالکیّت و فرمانروایی اوست، و نیز دین ثابت و پایدار مخصوص اوست؛ آیا از غیر او پروا می کنید؟!', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (482125, 16, 78, 14, 1953, 'وله ما في السماوات والأرض وله الدين واصبا ۚ أفغير الله تتقون', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (35916, 52, 6, 27, 4736, 'Při HOŘE,', 1, 7, 523, 458, NULL, 209, 53);
INSERT INTO quranhub_schema.ayat VALUES (126679, 16, 21, 14, 1959, 'When the glad news of the birth of their daughter is brought to them, their faces turn gloomy and black with anger.', 58, 3, 273, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (488361, 16, 79, 14, 1953, 'وَلَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَلَهُ الدِّينُ وَاصِبًا ۚ أَفَغَيْرَ اللَّهِ تَتَّقُونَ', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (494597, 16, 80, 14, 1953, 'وَلَهُ ما فِي السَّماواتِ وَالأَرضِ وَلَهُ الدّينُ واصِبًا ۚ أَفَغَيرَ اللَّهِ تَتَّقونَ', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (500833, 16, 81, 14, 1953, 'وَلَهُ ما فِى السَّمٰوٰتِ وَالأَرضِ وَلَهُ الدّينُ واصِبًا ۚ أَفَغَيرَ اللَّهِ تَتَّقونَ', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (507069, 16, 82, 14, 1953, 'وَلَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَلَهُ ٱلدِّينُ وَاصِبًا ۚ أَفَغَيْرَ ٱللَّهِ تَتَّقُونَ', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (513305, 16, 83, 14, 1953, 'И Негово е всичко на небесата и на земята, и неизменно за Него е служенето. И нима се боите от друг освен от Аллах?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (519541, 16, 84, 14, 1953, 'A Njegovo je šta je na nebesima i Zemlji, i Njemu pripada vjera trajna. Pa zar ćete se drugog (a ne) Allaha bojati?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (525777, 16, 85, 14, 1953, 'و آنچه در آسمان‌ها و زمين است از آن اوست، و دين و بندگى نيز هميشه براى اوست، پس آيا از غير خدا مى‌ترسيد', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (532013, 16, 86, 14, 1953, 'Y Suyo es todo lo que hay en los cielos y en la tierra, y [sólo] a Él es debida la obediencia siempre: ¿vais, pues, a rendir veneración a algo distinto de Dios?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (538249, 16, 87, 14, 1953, 'و آنچه در آسمانها و زمين است، از آن اوست، و دين پايدار از آن اوست، آيا از غير خداوند پروا داريد؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (544485, 16, 88, 14, 1953, 'و او راست آنچه در آسمانها و زمين است و پرستش و فرمانبردارى هميشه و پيوسته براى اوست. آيا از غير خداى يكتا پروا مى‌كنيد؟!', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (550721, 16, 89, 14, 1953, 'जो कुछ आकाशों और धरती में है सब उसी का है। उसी का दीन (धर्म) स्थायी और अनिवार्य है। फिर क्या अल्लाह के सिवा तुम किसी और का डर रखोगे?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (556957, 16, 90, 14, 1953, 'Hanya kepunyaan-Nyalah penciptaan, kepemilikan dan penghambaan segala apa yang ada di langit dan di bumi. Maka Dialah, tidak selain-Nya, yang berhak untuk disembah, dipuji, ditaati, diharapkan kasih sayang-Nya dan ditakuti siksa-Nya.', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (563193, 16, 91, 14, 1953, 'Dan bagiNyalah (hak milik) segala yang ada di langit dan di bumi; dan kepadaNya sahaja tertentu ibadat dan ketaatan selama-lamanya; (sesudah kamu mengetahui yang demikian) maka tidaklah patut kamu takut kepada yang lain dari Allah.', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (569429, 16, 92, 14, 1953, 'И Ему [Аллаху] принадлежит то, что в небесах и на земле [Он является Создателем, Владыкой и Богом всего], и Ему (должно совершаться) поклонение постоянно. Неужели вы будете остерегаться [бояться] кого-нибудь, кроме Аллаха?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (575665, 16, 93, 14, 1953, 'Ему принадлежит то, что в небесах и на земле, Ему - подчинение постоянное; неужели вы боитесь кого-нибудь, кроме Аллаха?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (581901, 16, 94, 14, 1953, 'Ему, Единому, принадлежит всё в небесах и на земле: все люди - и цари, и рабы! Вам следует поклоняться Аллаху Единому и благодарить Его, а не кого-то другого. Аллаху следует повиноваться, просить у Него прощения и бояться Его наказания!', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (588137, 16, 95, 14, 1953, 'В Его власти все, что на небесах и на земле: Ему подобает постоянное служение; потому, следует ли вам благоговеть пред кем либо другим, кроме Бога?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (594373, 16, 96, 14, 1953, 'آسمانوں میں اور زمین میں جو کچھ ہے سب اسی کا ہے اور اسی کی عبادت ﻻزم ہے، کیا پھر تم اس کے سوا اوروں سے ڈرتے ہو؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (600609, 16, 97, 14, 1953, 'اُسی کا ہے وہ سب کچھ جو آسمانوں میں ہے اور جو زمین میں ہے، اور خالصاً اُسی کا دین (ساری کائنات میں) چل رہا ہے پھر کیا اللہ کو چھوڑ کر تم کسی اور سے تقویٰ کرو گے؟', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (606845, 16, 98, 14, 1953, '天地万物只是他的，顺从常常只归于他。难道你们舍真主而敬畏他物吗？', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (613081, 16, 99, 14, 1953, '天地萬物只是他的，順從常常只歸於他。難道你們捨真主而敬畏他物嗎？', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (619317, 16, 100, 14, 1953, 'آنچه در آسمانها و زمین است از آن او است، و همواره (تعیین نحوه‌ی) دینداری و (کار) قانونگذاری حق او، و اطاعت و انقیاد از وی واجب و لازم است. پس (وقتی که عالَم هستی از آنِ خدا و قوانین تکوینی و تشریعی و اطاعت و انقیاد همه چیز و همگان از او است) آیا از غیر خدا می‌ترسید؟ [[«الدِّینُ»: دین و شریعت. قوانین و سنن. اطاعت و انقیاد. «وَاصِباً»: همیشه و همواره (نگا: صافّات / 9). واجب و لازم. خالصانه. این واژه حال (الدّینُ) است.]]', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (625553, 16, 101, 14, 1953, 'و برای او است آنچه در آسمانها و زمین است و برای او است دین پیوسته پس آیا جز خدای را می‌پرهیزید', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (631789, 16, 102, 14, 1953, 'Sve što je na nebesima i na Zemlji Njegovo je i Njemu treba uvijek poslušan biti. Zar nekog drugog, osim Allaha, da se bojite?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (638025, 16, 103, 14, 1953, '«وله ما في السماوات والأرض» ملكاً وخلقاً وعبيداً «وله الدين» الطاعة «واصباً» دائماً حال من الدين والعامل فيه معنى الظرف «أفغير الله تتقون» وهو الإله الحق ولا إله غيره والاستفهام للإنكار والتوبيخ.', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (644261, 16, 104, 14, 1953, 'وَلَهُ[n[ۥ] مَا فِى [h:609[ٱ][l[ل]سَّمَ[n[ـٰ]و[n[َٲ]تِ وَ[h:177[ٱ]لْأَرْضِ وَلَهُ [h:7431[ٱ][l[ل]دِّينُ وَاصِبًا‌ۚ أَفَغَيْرَ [h:4347[ٱ]للَّهِ تَتَّق[p[ُو]نَ', 52, 3, 272, 230, NULL, 109, 28);
