INSERT INTO quranhub_schema.ayat VALUES (656733, 16, 132, 14, 1953, 'وَلَهُۥ|And to Him (belongs)|159|170|2408$مَا|whatever|82|104|262$فِى|(is) in|58|80|89$ٱلسَّمَـٰوَٲتِ|the heavens|115|137|351$وَٱلْأَرْضِ|and the earth|111|133|352$وَلَهُ|and to Him|91|102|5732$ٱلدِّينُ|(is due) the worship|153|168|1697$وَاصِبًا‌ۚ|constantly.|95|126|9985$أَفَغَيْرَ|Then is it other (than)|169|200|3061$ٱللَّهِ|Allah|53|84|606$تَتَّقُونَ|you fear?|82|97|194$', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (662969, 16, 133, 14, 1953, 'walahu,⚓And to Him (belongs)⚓PRON|3MS★maA⚓whatever⚓ REL|LEM:maA★fiY⚓(is) in⚓ P|LEM:fiY★{ls~ama`wa`ti⚓the heavens⚓ N|LEM:samaA^''|ROOT:smw|FP|GEN★wa{lo>aroDi⚓and the earth⚓ N|LEM:>aroD|ROOT:ArD|F|GEN★walahu⚓and to Him⚓ PRON|3MS★{ld~iynu⚓(is due) the worship⚓ N|LEM:diyn|ROOT:dyn|M|NOM★waASibFA⚓constantly.⚓ N|ACT|PCPL|LEM:waASib|ROOT:wSb|M|INDEF|ACC★>afagayora⚓Then is it other (than)⚓ N|LEM:gayor|ROOT:gyr|M|ACC★{ll~ahi⚓Allah⚓ PN|LEM:{ll~ah|ROOT:Alh|GEN★tat~aquwna⚓you fear?⚓ V|IMPF|(VIII)|LEM:{t~aqaY`|ROOT:wqy|2MP★', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (669205, 16, 134, 14, 1953, 'අහස්හිද, භූමියෙහිද ඇති සියල්ල ඔහුටම අයත් දැයයි! ඔහුටම (සදාකල්) අවනත වීම අත්‍යාවශ්‍යය. (එබැවින්) එම අල්ලාහ් නොවන දැයටද ඔබ බිය වන්නේ?', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (675441, 16, 135, 14, 1953, 'walahu, maA fiY {ls~ama`wa`ti wa{lo>aroDi walahu {ld~iynu waASibFA >afagayora {ll~ahi tat~aquwna', 52, 3, 272, 230, NULL, 109, 28);
INSERT INTO quranhub_schema.ayat VALUES (681677, 16, 136, 14, 1953, '天地间的一切都是他的，顺从永远只归他[顺从安拉是人类的义务]。难道你们还要舍安拉而敬畏其他神灵吗？', 52, 3, 272, 230, NULL, 109, 28);
