INSERT INTO quranhub_schema.narrations_differences VALUES (1, 1, 3, 150, 'الرحيم مالك', 'قرأ بالإظهار.');
INSERT INTO quranhub_schema.narrations_differences VALUES (2, 1, 4, 150, 'مالك', 'قرأ (مَـلِـكِ) بحذف الألف بين الميم واللام.');
INSERT INTO quranhub_schema.narrations_differences VALUES (3, 1, 5, 150, 'وإياك', 'قرأ بتحقيق الهمزة وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (4, 1, 6, 150, 'الصراط', 'قرأ بالصاد الخالصة.');
INSERT INTO quranhub_schema.narrations_differences VALUES (5, 1, 7, 150, 'صراط', 'قرأ بالصاد الخالصة.');
INSERT INTO quranhub_schema.narrations_differences VALUES (6, 1, 7, 150, 'عليهم', 'قرأ بكسر هاء الضمير وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (7, 1, 7, 150, 'عليهم غير', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (8, 1, 7, 150, 'عليهم ولا', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (9, 1, 7, 150, 'الضالين بسم - الضالين الم', 'فصل بالبسملة بين السورتين.');
INSERT INTO quranhub_schema.narrations_differences VALUES (10, 2, 1, 150, 'الم', 'قرأ بترك السكت على حروف الهجاء.');
INSERT INTO quranhub_schema.narrations_differences VALUES (11, 2, 2, 150, 'فيه هدى', 'قرأ بصلة هاء الضمير خلافا لجمهور القراء.');
INSERT INTO quranhub_schema.narrations_differences VALUES (12, 2, 2, 150, 'هدى', 'قرأ بالفتح بلا خلاف عنه وقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (13, 2, 3, 150, 'يؤمنون', 'قرأ بتحقيق الهمزة الساكنة وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (14, 2, 3, 150, 'الصلاة', 'قرأ بترقيق اللام.');
INSERT INTO quranhub_schema.narrations_differences VALUES (15, 2, 3, 150, 'رزقناهم ينفقون', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (16, 2, 4, 150, 'يؤمنون', 'قرأ بتحقيق الهمزة الساكنة وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (17, 2, 4, 150, 'وبالآخرة', 'قرأ بترك السكت، مع تفخيم الراء، وقصر مد البدل، وفتح هاء التأنيث.');
INSERT INTO quranhub_schema.narrations_differences VALUES (18, 2, 4, 150, 'هم يوقنون', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (19, 2, 5, 150, 'أولئك', 'قرأ بتحقيق الهمزة وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (20, 2, 5, 150, 'هدى', 'قرأ بالفتح بلا خلاف عنه وقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (21, 2, 5, 150, 'ربهم وأولئك', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (22, 2, 5, 150, 'وأولئك', 'قرأ بتحقيق الهمزتين وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (23, 2, 6, 150, 'سواء', 'قرأ بتحقيق الهمزة المتطرفة وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (24, 2, 6, 150, 'عليهم', 'قرأ بكسر هاء الضمير وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (25, 2, 6, 150, 'عليهم أأنذرتهم', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (26, 2, 6, 150, 'أأنذرتهم', 'قرأ بتسهيل الهمزة الثانية، بلا إدخال.');
INSERT INTO quranhub_schema.narrations_differences VALUES (27, 2, 6, 150, 'أأنذرتهم أم', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (28, 2, 6, 150, 'تنذرهم لا', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (29, 2, 6, 150, 'يؤمنون', 'قرأ بتحقيق الهمزة الساكنة وصلاً ووقفاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (30, 2, 7, 150, 'قلوبهم وعلى', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (31, 2, 7, 150, 'سمعهم وعلى', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (32, 2, 7, 150, 'أبصارهم', 'قرأ بالفتح بلا خلاف.');
INSERT INTO quranhub_schema.narrations_differences VALUES (33, 2, 7, 150, 'أبصارهم غشاوة', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (34, 2, 7, 150, 'غشاوة', 'قرأ بفتح هاء التأنيث.');
INSERT INTO quranhub_schema.narrations_differences VALUES (35, 2, 7, 150, 'غشاوة ولهم', 'قرأ بالإدغام مع الغنة.');
INSERT INTO quranhub_schema.narrations_differences VALUES (36, 2, 7, 150, 'ولهم عذاب', 'قرأ بصلة ميم الجمع وصلاً.');
INSERT INTO quranhub_schema.narrations_differences VALUES (37, 2, 7, 150, 'عظيم ومن', 'قرأ بالإدغام مع الغنة.');
INSERT INTO quranhub_schema.narrations_differences VALUES (38, 2, 8, 150, 'الناس', 'قرأ بالفتح بلا خلاف عنه.');
